function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const asset = assets[url.pathname] || assets['/index.html'];
    const body = asset.encoding === 'base64' ? decodeBase64(asset.body) : asset.body;
    return new Response(body, {
      headers: {
        'content-type': asset.contentType,
        'cache-control': url.pathname === '/' || url.pathname === '/index.html' ? 'no-store, max-age=0, must-revalidate' : 'public, max-age=31536000, immutable'
      }
    });
  }
};
